mapper.select:
SELECT v.VOUCHER_ID, v.MODEL_ID, v.TEMPLATE_ID, v.PERIOD, v.VOUCHER_NO, v.VOUCHER_DATE, v.ENTRY_TYPE, v.ACCOUNT_CODE, v.ACCOUNT_NAME, v.AMOUNT, v.ORG_ID, v.ORG_NAME, v.DESCRIPTION, v.STATUS, v.TENANT_ID, v.CREATE_USER, v.CREATE_TIME, v.UPDATE_USER, v.UPDATE_TIME, m.MODEL_NAME, t.TEMPLATE_NAME FROM TBL_ELIMINATION_VOUCHER v LEFT JOIN TBL_CONSOLIDATION_MODEL m ON v.MODEL_ID = m.MODEL_ID LEFT JOIN TBL_ELIMINATION_TEMPLATE t ON v.TEMPLATE_ID = t.TEMPLATE_ID
AND v.MODEL_ID = #{param.modelId}
AND v.PERIOD = #{param.period}
AND v.VOUCHER_NO = #{param.voucherNo}
AND v.TEMPLATE_ID = #{param.templateId}
AND v.STATUS = #{param.status}
ORDER BY v.VOUCHER_NO ASC, v.ENTRY_TYPE DESC, v.CREATE_TIME ASC

mapper.delete:
DELETE FROM TBL_ELIMINATION_VOUCHER
WHERE MODEL_ID = #{modelId}
AND PERIOD = #{period}

mapper.select:
SELECT DISTINCT VOUCHER_NO
FROM TBL_ELIMINATION_VOUCHER
WHERE MODEL_ID = #{modelId}
AND PERIOD = #{period}
ORDER BY VOUCHER_NO ASC

mapper.update:
UPDATE TBL_ELIMINATION_VOUCHER
SET STATUS = #{status}
WHERE MODEL_ID = #{modelId}
AND PERIOD = #{period}
